package com.fitbite.service; import com.fitbite.entity.User; import com.fitbite.exception.ResourceNotFoundException; import com.fitbite.repository.UserRepository; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service;
@Service public class CurrentUserService { private final UserRepository users; public CurrentUserService(UserRepository users){this.users=users;} public User get(){String email=SecurityContextHolder.getContext().getAuthentication().getName();return users.findByEmailIgnoreCase(email).orElseThrow(()->new ResourceNotFoundException("User not found"));} }
